#requires -Version 5.1
[CmdletBinding()]
param(
    [ValidateSet('Help','List','Run','Show','ExportSql')]
    [string]$Action = 'Help',
    [string]$Name,
    [string]$OutputPath
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$SolutionRoot = Split-Path -Parent $PSScriptRoot

function Decode-Content {
    param([Parameter(Mandatory = $true)][string]$Base64Value)
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Base64Value))
}

$Sections = [ordered]@{
    'Build & Startup' = @('build-all.ps1', 'start_all.ps1', 'start-dev.ps1', 'start_api.ps1', 'setup_database.ps1')
    'Azure Deployment & Verification' = @('deploy-dashboard.ps1', 'deploy-python-watcher.ps1', 'deploy-watcher-github.ps1', 'build-and-deploy-fix.ps1', 'run-azure-migration.ps1', 'fix-azure-settings.ps1', 'check-azure-deployment.ps1', 'verify-azure-deployment.ps1', 'check-status.ps1')
    'Testing & Diagnostics' = @('debug-test.ps1', 'test-blob-storage.ps1', 'test_analysis_ingest.ps1', 'diagnose-google-models.ps1')
    'Data Maintenance & Cleanup' = @('Analyze-ExistingReports.ps1', 'clean-production-data.ps1', 'cleanup-production-data.ps1', 'remove-emojis.ps1', 'Seed-SaudiGccTenderSources.ps1')
}

$EmbeddedPowerShell = @{
    'Analyze-ExistingReports.ps1' = ''
    'build-all.ps1' = ''
    'build-and-deploy-fix.ps1' = ''
    'check-azure-deployment.ps1' = ''
    'check-status.ps1' = ''
    'clean-production-data.ps1' = ''
    'cleanup-production-data.ps1' = ''
    'debug-test.ps1' = ''
    'deploy-dashboard.ps1' = ''
    'deploy-python-watcher.ps1' = ''
    'deploy-watcher-github.ps1' = ''
    'diagnose-google-models.ps1' = ''
    'fix-azure-settings.ps1' = ''
    'remove-emojis.ps1' = ''
    'run-azure-migration.ps1' = ''
    'Seed-SaudiGccTenderSources.ps1' = ''
    'setup_database.ps1' = ''
    'start-dev.ps1' = ''
    'start_all.ps1' = ''
    'start_api.ps1' = ''
    'test-blob-storage.ps1' = ''
    'test_analysis_ingest.ps1' = ''
    'verify-azure-deployment.ps1' = ''
}

$EmbeddedSql = @{
    'cleanup-database.sql' = ''
    'cleanup-reports.sql' = ''
    'CREATE_CONTACT_TABLES.sql' = ''
    'FIX_FILE_PATHS.sql' = ''
}

function Show-Help {
    Write-Host ''
    Write-Host 'Alfanar MarketIntel Toolkit' -ForegroundColor Cyan
    Write-Host '================================' -ForegroundColor Cyan
    Write-Host 'Actions:' -ForegroundColor Yellow
    Write-Host '  -Action Help'
    Write-Host '  -Action List'
    Write-Host '  -Action Run -Name <script name>'
    Write-Host '  -Action Show -Name <script/sql name>'
    Write-Host '  -Action ExportSql -Name <sql name> [-OutputPath <file>]'
    Write-Host ''
    Write-Host 'Examples:' -ForegroundColor Yellow
    Write-Host '  .\MarketIntel-Toolkit.ps1 -Action List'
    Write-Host '  .\MarketIntel-Toolkit.ps1 -Action Run -Name start_all.ps1'
    Write-Host '  .\MarketIntel-Toolkit.ps1 -Action ExportSql -Name cleanup-database.sql -OutputPath .\cleanup-database.sql'
}

function Invoke-EmbeddedScript {
    param([Parameter(Mandatory = $true)][string]$Name)
    if (-not $EmbeddedPowerShell.ContainsKey($Name)) { throw "Unknown script: $Name" }
    $tempFile = Join-Path $env:TEMP ("marketintel_" + ([System.IO.Path]::GetFileNameWithoutExtension($Name)) + "_" + [guid]::NewGuid().ToString("N") + ".ps1")
    Set-Content -Path $tempFile -Value (Decode-Content $EmbeddedPowerShell[$Name]) -Encoding UTF8
    try {
        Push-Location $SolutionRoot
        & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tempFile
        if ($LASTEXITCODE -ne 0) { throw "Embedded script exited with code $LASTEXITCODE" }
    }
    finally {
        Pop-Location
        Remove-Item $tempFile -Force -ErrorAction SilentlyContinue
    }
}

function Export-EmbeddedSql {
    param([Parameter(Mandatory = $true)][string]$Name, [string]$TargetPath)
    if (-not $EmbeddedSql.ContainsKey($Name)) { throw "Unknown SQL asset: $Name" }
    if (-not $TargetPath) { $TargetPath = Join-Path $PSScriptRoot $Name }
    Set-Content -Path $TargetPath -Value (Decode-Content $EmbeddedSql[$Name]) -Encoding UTF8
    Write-Host "Exported $Name to $TargetPath" -ForegroundColor Green
}

switch ($Action.ToLowerInvariant()) {
    'help' { Show-Help }
    'list' {
        foreach ($sectionName in $Sections.Keys) {
            Write-Host "`n[$sectionName]" -ForegroundColor Yellow
            foreach ($item in $Sections[$sectionName]) { Write-Host " - $item" }
        }
        if ($EmbeddedSql.Count -gt 0) {
            Write-Host "`n[SQL Assets]" -ForegroundColor Yellow
            foreach ($item in ($EmbeddedSql.Keys | Sort-Object)) { Write-Host " - $item" }
        }
    }
    'show' {
        if (-not $Name) { throw 'Provide -Name for Show.' }
        if ($EmbeddedPowerShell.ContainsKey($Name)) { Decode-Content $EmbeddedPowerShell[$Name] | Write-Output }
        elseif ($EmbeddedSql.ContainsKey($Name)) { Decode-Content $EmbeddedSql[$Name] | Write-Output }
        else { throw "Asset not found: $Name" }
    }
    'run' {
        if (-not $Name) { throw 'Provide -Name for Run.' }
        Invoke-EmbeddedScript -Name $Name
    }
    'exportsql' {
        if (-not $Name) { throw 'Provide -Name for ExportSql.' }
        Export-EmbeddedSql -Name $Name -TargetPath $OutputPath
    }
    default { Show-Help }
}
